from __future__ import annotations


def citation_map_html() -> str:
	return """<!doctype html>
<html lang="en">
<head>
	<meta charset="utf-8">
	<meta name="viewport" content="width=device-width, initial-scale=1">
	<title>Citation Map | AI CaseLibrary</title>
	<link rel="preconnect" href="https://fonts.googleapis.com">
	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
	<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=Newsreader:opsz,wght@6..72,600;6..72,700&display=swap" rel="stylesheet">
	<script src="https://unpkg.com/lucide@0.468.0/dist/umd/lucide.min.js"></script>
	<style>
		:root { --ink:#202522; --muted:#69726d; --paper:#f1efe8; --surface:#fffef9; --line:#d8d5ca; --rust:#a4412b; --teal:#176c68; --gold:#c28e2d; --blue:#315d8d; }
		* { box-sizing:border-box; }
		body { margin:0; min-height:100vh; color:var(--ink); font-family:"IBM Plex Sans",sans-serif; letter-spacing:0; background:var(--paper); background-image:linear-gradient(rgba(32,37,34,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(32,37,34,.035) 1px,transparent 1px); background-size:26px 26px; }
		button,input { font:inherit; letter-spacing:0; } button { cursor:pointer; }
		.topbar { height:68px; display:flex; align-items:center; justify-content:space-between; gap:24px; padding:0 24px; border-bottom:1px solid var(--line); background:rgba(255,254,249,.95); }
		.brand { display:flex; align-items:baseline; gap:13px; min-width:0; } .brand h1 { margin:0; font:700 28px/1 "Newsreader",serif; } .brand span { color:var(--muted); font-size:12px; }
		.stats { display:flex; gap:22px; } .stat strong { display:block; font-size:14px; } .stat span { color:var(--muted); font-size:10px; text-transform:uppercase; }
		.shell { display:grid; grid-template-columns:280px minmax(480px,1fr) 330px; height:calc(100vh - 68px); }
		.left,.center,.right { min-width:0; } .left,.right { min-height:0; background:rgba(255,254,249,.92); } .left { border-right:1px solid var(--line); } .right { border-left:1px solid var(--line); }
		.left-head { padding:18px; border-bottom:1px solid var(--line); } h2 { margin:0; font:600 20px/1.15 "Newsreader",serif; }
		.search { position:relative; margin-top:12px; } .search>i { position:absolute; z-index:2; left:11px; top:10px; width:17px; color:var(--muted); }
		.search input { width:100%; height:38px; padding:8px 10px 8px 36px; border:1px solid var(--line); border-radius:5px; outline:0; background:var(--surface); color:var(--ink); }
		.search input:focus { border-color:var(--teal); box-shadow:0 0 0 2px rgba(23,108,104,.1); }
		.search-results { position:absolute; z-index:8; top:42px; left:0; right:0; max-height:360px; overflow:auto; border:1px solid var(--line); border-radius:5px; background:var(--surface); box-shadow:0 12px 30px rgba(32,37,34,.16); }
		.search-results:empty { display:none; }
		.result-button,.start-button { width:100%; padding:11px 12px; border:0; border-bottom:1px solid #ebe8df; background:transparent; text-align:left; color:var(--ink); }
		.result-button:hover,.start-button:hover,.start-button.active { background:#edf3f0; } .start-button.active { box-shadow:inset 3px 0 var(--teal); }
		.result-button strong,.start-button strong { display:block; font-size:12px; line-height:1.3; } .result-button small,.start-button small { display:block; margin-top:3px; color:var(--muted); font-size:11px; line-height:1.35; }
		.section-label { padding:16px 18px 8px; color:var(--muted); font-size:10px; font-weight:600; text-transform:uppercase; }
		.starting-points { overflow:auto; max-height:calc(100% - 142px); } .empty { padding:20px 18px; color:var(--muted); font-size:12px; line-height:1.5; }
		.center { display:grid; grid-template-rows:auto minmax(0,1fr) auto; min-width:0; min-height:0; }
		.map-head { display:flex; align-items:center; justify-content:space-between; gap:18px; padding:15px 20px; border-bottom:1px solid var(--line); background:rgba(241,239,232,.88); }
		.map-title { min-width:0; } .map-title strong { display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; } .map-title span { color:var(--muted); font-size:11px; }
		.icon-button { width:36px; height:36px; display:grid; place-items:center; flex:0 0 auto; border:1px solid var(--line); border-radius:5px; color:var(--ink); background:var(--surface); } .icon-button:hover { color:var(--teal); border-color:var(--teal); } .icon-button i { width:17px; }
		.map { position:relative; min-height:0; overflow:hidden; background:rgba(255,254,249,.65); } #mapSvg { display:block; width:100%; height:100%; }
		.map-empty { position:absolute; inset:0; display:grid; place-items:center; padding:30px; text-align:center; color:var(--muted); } .map-empty i { width:38px; height:38px; margin-bottom:10px; }
		.legend { position:absolute; left:16px; bottom:14px; display:flex; gap:14px; padding:7px 9px; border:1px solid var(--line); border-radius:5px; background:rgba(255,254,249,.94); color:var(--muted); font-size:10px; }
		.legend span { display:flex; align-items:center; gap:5px; } .dot { width:8px; height:8px; border-radius:50%; }
		.authority-strip { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); border-top:1px solid var(--line); background:var(--surface); }
		.authority-chip { min-width:0; min-height:74px; padding:10px; border:0; border-right:1px solid #e9e6dd; background:transparent; text-align:left; color:var(--ink); } .authority-chip:hover,.authority-chip.active { background:#edf3f0; }
		.authority-chip strong { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:11px; } .authority-chip small { display:block; margin-top:4px; color:var(--muted); font-size:10px; line-height:1.3; }
		.case-card { padding:18px; border-bottom:1px solid var(--line); } .case-card .citation { color:var(--rust); font-size:12px; font-weight:600; } .case-card h2 { margin:5px 0 8px; font-size:20px; line-height:1.2; } .case-card p { margin:0; color:var(--muted); font-size:11px; line-height:1.45; }
		.primary-button { display:flex; align-items:center; justify-content:center; gap:7px; width:100%; height:36px; margin-top:13px; border:0; border-radius:5px; background:var(--ink); color:#fff; font-size:12px; } .primary-button:hover { background:var(--teal); } .primary-button i { width:15px; }
		.tabs { display:grid; grid-template-columns:repeat(3,1fr); border-bottom:1px solid var(--line); } .tab { padding:11px 5px; border:0; background:transparent; color:var(--muted); font-size:11px; } .tab.active { color:var(--ink); box-shadow:inset 0 -2px var(--rust); }
		.detail-list { height:calc(100% - 240px); overflow:auto; } .detail-row { padding:12px 16px; border-bottom:1px solid #e9e6dd; } .detail-row strong { display:block; font-size:12px; line-height:1.35; } .detail-row small { display:block; margin-top:4px; color:var(--muted); font-size:10px; line-height:1.4; } .detail-row button { margin-top:7px; padding:0; border:0; color:var(--blue); background:transparent; font-size:11px; }
		.badge { display:inline-block; margin-top:7px; padding:2px 6px; border-radius:3px; background:#eee8d9; color:#66521f; font-size:10px; } .loading { opacity:.55; pointer-events:none; }
		@media(max-width:1050px) { .shell { height:auto; grid-template-columns:250px minmax(460px,1fr); } .left,.center { height:calc(100vh - 68px); } .right { grid-column:1/-1; height:520px; border-top:1px solid var(--line); border-left:0; } }
		@media(max-width:720px) { .topbar { padding:10px 14px; } .brand span,.stats .stat:nth-child(n+3) { display:none; } .stats { gap:11px; } .shell { grid-template-columns:1fr; } .left { height:220px; border-right:0; border-bottom:1px solid var(--line); } .starting-points { display:flex; max-height:98px; overflow-x:auto; } .start-button { min-width:210px; border-right:1px solid #ebe8df; } .center { height:650px; } .right { grid-column:1; height:520px; } .authority-strip { overflow-x:auto; grid-template-columns:repeat(5,160px); } }
	</style>
</head>
<body>
	<header class="topbar">
		<div class="brand"><h1>Citation Map</h1><span>Case authority explorer</span></div>
		<div class="stats"><div class="stat"><strong id="statCases">-</strong><span>Cases</span></div><div class="stat"><strong id="statEdges">-</strong><span>Links</span></div><div class="stat"><strong id="statResolved">-</strong><span>Resolved</span></div></div>
	</header>
	<main class="shell">
		<aside class="left">
			<div class="left-head"><h2>Find a case</h2><div class="search"><i data-lucide="search"></i><input id="caseSearch" type="search" autocomplete="off" placeholder="Citation or case name"><div id="searchResults" class="search-results"></div></div></div>
			<div class="section-label">Starting points</div><div id="startingPoints" class="starting-points"><div class="empty">Loading...</div></div>
		</aside>
		<section class="center">
			<div class="map-head"><div class="map-title"><strong id="mapTitle">Select a case</strong><span id="mapSubtitle">Five influential authorities cited by the selected case</span></div><button id="refreshButton" class="icon-button" title="Refresh map" aria-label="Refresh map"><i data-lucide="refresh-cw"></i></button></div>
			<div id="map" class="map"><svg id="mapSvg" role="img" aria-label="Five-authority citation map"></svg><div id="mapEmpty" class="map-empty"><div><i data-lucide="git-fork"></i><div>No case selected</div></div></div><div class="legend"><span><i class="dot" style="background:var(--rust)"></i>Selected case</span><span><i class="dot" style="background:var(--teal)"></i>Cited authority</span><span>Line width = mentions</span></div></div>
			<div id="authorityStrip" class="authority-strip"></div>
		</section>
		<aside class="right"><div id="caseCard" class="case-card"><span class="citation">No selection</span><h2>Case details</h2><p>Select a case or authority to inspect it.</p></div><div class="tabs"><button class="tab active" data-tab="authorities">Authorities</button><button class="tab" data-tab="similar">Related</button><button class="tab" data-tab="coCited">Co-cited</button></div><div id="detailList" class="detail-list"><div class="empty">No results yet.</div></div></aside>
	</main>
	<script>
		const state={starting:[],focusId:null,inspectedId:null,map:null,similar:[],coCited:[],activeTab:'authorities',searchTimer:null};
		const fmt=(value)=>new Intl.NumberFormat('en-CA').format(Number(value||0));
		const esc=(value)=>String(value??'').replace(/[&<>'\"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[char]));
		async function getJson(url){const response=await fetch(url);if(!response.ok)throw new Error(`Request failed: ${response.status}`);return response.json();}
		function nodeById(id){return state.map?.nodes.find((node)=>node.case_id===id)||null;}
		function renderStarting(){document.getElementById('startingPoints').innerHTML=state.starting.map((item)=>`<button class="start-button ${item.case_id===state.focusId?'active':''}" data-id="${item.case_id}"><strong>${esc(item.citation||item.title)}</strong><small>${esc(item.title)}<br>${fmt(item.citing_cases)} citing cases</small></button>`).join('');document.querySelectorAll('.start-button').forEach((button)=>button.addEventListener('click',()=>selectCase(Number(button.dataset.id))));}
		function renderSearchResults(rows){const element=document.getElementById('searchResults');element.innerHTML=rows.map((item)=>`<button class="result-button" data-id="${item.case_id}"><strong>${esc(item.citation||item.title)}</strong><small>${esc(item.title)} · ${esc(item.court)} · ${esc(item.date)}</small></button>`).join('')||(document.getElementById('caseSearch').value.trim()?'<div class="empty">No matching cases.</div>':'');element.querySelectorAll('.result-button').forEach((button)=>button.addEventListener('click',()=>{selectCase(Number(button.dataset.id));element.innerHTML='';document.getElementById('caseSearch').value='';}));}
		function positions(width,height,count){const center={x:width/2,y:height/2};const radius=Math.min(width*.36,height*.34);return[center,...Array.from({length:count},(_,index)=>{const angle=(-Math.PI/2)+(Math.PI*2*index/count);return{x:center.x+Math.cos(angle)*radius,y:center.y+Math.sin(angle)*radius};})];}
		function renderMap(){const svg=document.getElementById('mapSvg'),frame=document.getElementById('map');const width=Math.max(460,frame.clientWidth),height=Math.max(430,frame.clientHeight);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.innerHTML='';if(!state.map)return;document.getElementById('mapEmpty').style.display=state.map.edges.length?'none':'grid';if(!state.map.edges.length){document.getElementById('mapEmpty').innerHTML='<div><i data-lucide="circle-slash-2"></i><div>No resolved outgoing authorities for this case.</div></div>';lucide.createIcons();return;}const points=positions(width,height,state.map.nodes.length-1),byId=new Map(state.map.nodes.map((node,index)=>[node.case_id,{node,point:points[index]}]));const defs=document.createElementNS('http://www.w3.org/2000/svg','defs');defs.innerHTML='<marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#97988f"/></marker>';svg.appendChild(defs);for(const edge of state.map.edges){const source=byId.get(edge.source_case_id),target=byId.get(edge.target_case_id);if(!source||!target)continue;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',source.point.x);line.setAttribute('y1',source.point.y);line.setAttribute('x2',target.point.x);line.setAttribute('y2',target.point.y);line.setAttribute('stroke','#aaa99f');line.setAttribute('stroke-width',String(Math.min(7,1.5+Math.log2(edge.occurrence_count||1))));line.setAttribute('stroke-opacity','.75');line.setAttribute('marker-end','url(#arrow)');svg.appendChild(line);}for(const[nodeId,{node,point}]of byId){const focus=nodeId===state.focusId,active=nodeId===state.inspectedId;const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.style.cursor='pointer';group.addEventListener('click',()=>inspectNode(nodeId));const halo=document.createElementNS('http://www.w3.org/2000/svg','circle');halo.setAttribute('cx',point.x);halo.setAttribute('cy',point.y);halo.setAttribute('r',focus?'31':'26');halo.setAttribute('fill',active?'rgba(49,93,141,.14)':'transparent');halo.setAttribute('stroke',active?'#315d8d':'transparent');halo.setAttribute('stroke-width','2');group.appendChild(halo);const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('cx',point.x);circle.setAttribute('cy',point.y);circle.setAttribute('r',focus?'20':String(Math.min(18,10+Math.log10(Math.max(1,node.in_degree))*2)));circle.setAttribute('fill',focus?'#a4412b':'#176c68');circle.setAttribute('stroke','#fffef9');circle.setAttribute('stroke-width','3');group.appendChild(circle);const label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('x',point.x);label.setAttribute('y',point.y+(focus?39:34));label.setAttribute('text-anchor','middle');label.setAttribute('font-size',focus?'12':'11');label.setAttribute('font-weight','600');label.setAttribute('fill','#202522');label.textContent=(node.citation||node.title).slice(0,25);group.appendChild(label);const sub=document.createElementNS('http://www.w3.org/2000/svg','text');sub.setAttribute('x',point.x);sub.setAttribute('y',point.y+(focus?53:48));sub.setAttribute('text-anchor','middle');sub.setAttribute('font-size','9');sub.setAttribute('fill','#69726d');sub.textContent=focus?'Selected case':`${fmt(node.in_degree)} citing cases`;group.appendChild(sub);svg.appendChild(group);}}
		function renderStrip(){const authorities=state.map?.nodes.slice(1)||[];document.getElementById('authorityStrip').innerHTML=authorities.map((node,index)=>{const edge=state.map.edges[index];return`<button class="authority-chip ${node.case_id===state.inspectedId?'active':''}" data-id="${node.case_id}"><strong>${esc(node.citation||node.title)}</strong><small>${fmt(node.in_degree)} citing cases<br>${fmt(edge?.occurrence_count)} mention${edge?.occurrence_count===1?'':'s'} here</small></button>`;}).join('');document.querySelectorAll('.authority-chip').forEach((button)=>button.addEventListener('click',()=>inspectNode(Number(button.dataset.id))));}
		function inspectNode(caseId){state.inspectedId=caseId;renderMap();renderStrip();renderInspector();}
		function renderInspector(){const node=nodeById(state.inspectedId)||state.map?.focus;if(!node)return;const isFocus=node.case_id===state.focusId;document.getElementById('caseCard').innerHTML=`<span class="citation">${esc(node.citation||'No neutral citation')}</span><h2>${esc(node.title)}</h2><p>${esc(node.court)} · ${esc(node.date)}<br>${fmt(node.in_degree)} incoming · ${fmt(node.out_degree)} outgoing</p>${isFocus?'':`<button id="exploreButton" class="primary-button"><i data-lucide="git-fork"></i>Explore this case</button>`}`;document.getElementById('exploreButton')?.addEventListener('click',()=>selectCase(node.case_id));renderDetails();lucide.createIcons();}
		function renderDetails(){const list=document.getElementById('detailList');if(state.activeTab==='authorities'){const rows=state.map?.nodes.slice(1)||[];list.innerHTML=rows.map((node,index)=>`<div class="detail-row"><strong>${esc(node.citation||node.title)}</strong><small>${esc(node.title)}<br>${fmt(node.in_degree)} citing cases · ${fmt(state.map.edges[index]?.occurrence_count)} mentions in selected case</small><button data-inspect="${node.case_id}">Inspect authority</button></div>`).join('')||'<div class="empty">No resolved authorities found.</div>';}else if(state.activeTab==='similar'){list.innerHTML=state.similar.map((row)=>`<div class="detail-row"><strong>${esc(row.case.citation||row.case.title)}</strong><small>${esc(row.case.title)}<br>Shared: ${esc(row.shared_authorities.slice(0,3).map((item)=>item.citation||item.title).join(' · '))}</small><span class="badge">${row.shared_authority_count} shared authorities</span><br><button data-open="${row.case.case_id}">Map this case</button></div>`).join('')||'<div class="empty">No cases share enough resolved authorities yet.</div>';}else{list.innerHTML=state.coCited.map((row)=>`<div class="detail-row"><strong>${esc(row.authority.citation||row.authority.title)}</strong><small>${esc(row.authority.title)}</small><span class="badge">${fmt(row.shared_citing_cases)} shared citing cases</span><br><button data-open="${row.authority.case_id}">Map this authority</button></div>`).join('')||'<div class="empty">No co-citation results for this case.</div>';}list.querySelectorAll('[data-inspect]').forEach((button)=>button.addEventListener('click',()=>inspectNode(Number(button.dataset.inspect))));list.querySelectorAll('[data-open]').forEach((button)=>button.addEventListener('click',()=>selectCase(Number(button.dataset.open))));}
		async function selectCase(caseId){state.focusId=caseId;state.inspectedId=caseId;renderStarting();document.querySelector('.shell').classList.add('loading');try{const[map,similar,coCited]=await Promise.all([getJson(`/citation-map/cases/${caseId}/authority-map?limit=5`),getJson(`/citation-map/cases/${caseId}/similar?limit=12&min_shared=2`),getJson(`/citation-map/authorities/${caseId}/co-cited?limit=12`)]);state.map=map;state.similar=similar;state.coCited=coCited;document.getElementById('mapTitle').textContent=map.focus.citation||map.focus.title;document.getElementById('mapSubtitle').textContent=`${map.edges.length} influential cited authorities`;renderMap();renderStrip();renderInspector();}catch(error){document.getElementById('detailList').innerHTML=`<div class="empty">${esc(error.message)}</div>`;}finally{document.querySelector('.shell').classList.remove('loading');}}
		async function runSearch(){const query=document.getElementById('caseSearch').value.trim();if(query.length<2){renderSearchResults([]);return;}try{renderSearchResults(await getJson(`/citation-map/cases?q=${encodeURIComponent(query)}&limit=12`));}catch(error){document.getElementById('searchResults').innerHTML=`<div class="empty">${esc(error.message)}</div>`;}}
		async function load(){const[summary,starting]=await Promise.all([getJson('/citation-map/summary'),getJson('/citation-map/authorities?limit=6')]);document.getElementById('statCases').textContent=fmt(summary.total_cases);document.getElementById('statEdges').textContent=fmt(summary.aggregated_edges);document.getElementById('statResolved').textContent=fmt(summary.resolved_occurrences);state.starting=starting;renderStarting();if(starting.length)await selectCase(starting[0].case_id);}
		document.getElementById('caseSearch').addEventListener('input',()=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(runSearch,220);});document.getElementById('refreshButton').addEventListener('click',()=>state.focusId&&selectCase(state.focusId));document.querySelectorAll('.tab').forEach((tab)=>tab.addEventListener('click',()=>{state.activeTab=tab.dataset.tab;document.querySelectorAll('.tab').forEach((item)=>item.classList.toggle('active',item===tab));renderDetails();}));window.addEventListener('resize',renderMap);document.addEventListener('click',(event)=>{if(!event.target.closest('.search'))document.getElementById('searchResults').innerHTML='';});lucide.createIcons();load().catch((error)=>{document.getElementById('startingPoints').innerHTML=`<div class="empty">${esc(error.message)}</div>`;});
	</script>
</body>
</html>"""